// Math check app: every function of <cmath> (runtime/libm.c) and enaga::dsp's math on a spread of inputs, the
// results left in g_results for tests/test_math.py to read and compare with Python's double math. Its C file
// (check.c) checks that <math.h> serves C too.
#include <enaga/app.hpp>
#include <enaga/dsp/math.hpp>

#include <cmath>

extern "C" float math_from_c(float x);                  // check.c: sinf(x) + sqrtf(fabsf(x)) through <math.h>

